// ============================================================================
// src/lib/tools/python-playground/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the Python playground, two kinds, run by two steps:
//
//   PREFLIGHT_VECTORS  the pure preflight (compute.ts) on 42 inputs, one per
//                      finding code plus edge cases plus every example; run by
//                      scripts/run-golden-vectors.mts with every other tool.
//   ENGINE_VECTORS     the 12 examples' exact stdout, stderr and the repr of
//                      the last expression, measured by running them through
//                      the real engine (Pyodide 314.0.7, Python 3.14.2) under
//                      Node; re-measured by scripts/check-wasm-engines.mts at
//                      every build, so an engine upgrade that changes an
//                      example's output fails the build and is examined on
//                      purpose.
//
// Generated 2026-10-04 by the session's scratch generator from compute.ts and
// the pinned engine; the pin() shape is byte-exact on purpose.
// ============================================================================

import { preflight, type PlaygroundInput, type PreflightResult } from "./compute";

/** The set id (dated; a new date means the expectations were regenerated). */
export const GOLDEN_VECTOR_SET_ID = "python-playground-golden-2026-10-04";

/** One preflight vector. */
export interface PreflightVector {
  id: string;
  /** Why this input is in the set. */
  why: string;
  input: PlaygroundInput;
  /** The pinned shape: findings as "severity:code@line{params}", imports as "top:status(package)". */
  expect: { ok: boolean; findings: string[]; imports: string[]; stats: string };
}

/** One engine vector: an example's measured output. */
export interface EngineVector {
  /** The example id (compute.ts EXAMPLES). */
  id: string;
  stdout: string;
  stderr: string;
  /** repr() of the last expression's value, or null when the program ends in a statement or None. */
  result: string | null;
}

/** Pin a preflight result to the compact shape the vectors compare. */
export function pin(r: PreflightResult): PreflightVector["expect"] {
  return {
    ok: r.ok,
    findings: r.findings.map((f) => `${f.severity}:${f.code}${f.line ? "@" + f.line : ""}${f.params ? "{" + Object.entries(f.params).map(([k, v]) => `${k}=${v}`).join(";") + "}" : ""}`),
    imports: r.imports.map((i) => `${i.top}:${i.status}${i.packageName ? "(" + i.packageName + ")" : ""}`),
    stats: `lines=${r.stats.lines} stdin=${r.stats.stdinLines} reads=${r.stats.readsStdin ? 1 : 0} await=${r.stats.topLevelAwait ? 1 : 0} prints=${r.stats.prints ? 1 : 0} lastExpr=${r.stats.lastIsExpression ? 1 : 0}`,
  };
}

