/** All vectors, for the catalogue count. */
export const VECTORS = { preflight: PREFLIGHT_VECTORS, engine: ENGINE_VECTORS } as const;

/** Run the preflight vectors; the engine vectors need the engine and are run by check-wasm-engines. */
export function verifyVectors(): { setId: string; total: number; passed: number; failures: string[] } {
  const failures: string[] = [];
  for (const v of PREFLIGHT_VECTORS) {
    // Compare the pinned shape field by field so a failure names what moved.
    const got = pin(preflight(v.input));
    for (const key of ["ok", "findings", "imports", "stats"] as const) {
      const a = JSON.stringify(got[key]);
      const b = JSON.stringify(v.expect[key]);
      if (a !== b) failures.push(`${v.id}.${key}: expected ${b} got ${a}`);
    }
  }
  return { setId: GOLDEN_VECTOR_SET_ID, total: PREFLIGHT_VECTORS.length, passed: PREFLIGHT_VECTORS.length - new Set(failures.map((f) => f.split(".")[0])).size, failures };
}
